#!/bin/bash
set -e

# Optimization pass:
# - Patient Registration and Visit Creation (walk-in + appointment
#   check-in) were still awaiting the WhatsApp send inline (same class
#   of latency issue as the payment speed fix) -- now deferred via
#   after(), same as payments/actions.js already does.
# - Manual resend buttons (registration, visit) still work exactly as
#   before -- they use a separate synchronous path so you still get
#   real sent/error feedback when you click them.
# - Removed the throwaway /api/test-invoice-pdf diagnostic route.
# Run this from your veda-hmis repo root in Codespaces.

mkdir -p "app/(main)/patients"
echo "" | base64 -d > "app/(main)/patients/actions.js"
echo "Wrote app/(main)/patients/actions.js"

mkdir -p "app/(main)/visits"
echo "" | base64 -d > "app/(main)/visits/actions.js"
echo "Wrote app/(main)/visits/actions.js"

rm -rf "app/api/test-invoice-pdf"
echo "Removed throwaway app/api/test-invoice-pdf route"

git add -A
git commit -m "Optimize: defer registration/visit WhatsApp sends via after(); remove throwaway test route"
git push

echo "Done."
